package com.simon.offlinebms;
import org.json.*;
public final class EquipmentReading {
    public final long timestamp;public final String address,name;public final VictronProtocol.Data data;
    public EquipmentReading(long time,String address,String name,VictronProtocol.Data data){timestamp=time;this.address=address;this.name=name;this.data=data;}
    public JSONObject json()throws JSONException{JSONObject j=new JSONObject();j.put("timestamp_unix_ms",timestamp);j.put("address",address);j.put("name",name);j.put("record_type",data.type);j.put("model_id",data.model);j.put("counter",data.counter);j.put("state",data.state);j.put("alarm_flags",data.alarms);j.put("alarm_status_available",data.alarmsKnown);JSONObject values=new JSONObject(),units=new JSONObject();for(String key:data.values.keySet()){values.put(key,data.values.get(key));units.put(key,data.units.get(key));}j.put("values",values);j.put("units",units);JSONObject details=new JSONObject();for(String key:data.details.keySet())details.put(key,data.details.get(key));j.put("details",details);return j;}
    public static EquipmentReading parse(JSONObject j)throws JSONException{long time=j.getLong("timestamp_unix_ms");String address=j.getString("address"),name=j.getString("name");if(time<1262304000000L||time>System.currentTimeMillis()+86400000||!address.matches("(?i)[0-9a-f]{2}(:[0-9a-f]{2}){5}")||name.length()>160)throw new JSONException("Invalid equipment record");VictronProtocol.Data d=new VictronProtocol.Data();d.type=j.getInt("record_type");d.model=j.getInt("model_id");d.counter=j.getInt("counter");d.state=j.getInt("state");d.alarms=j.getLong("alarm_flags");d.alarmsKnown=j.optBoolean("alarm_status_available",true);if(d.type<0||d.type>255||d.model<0||d.model>65535||d.counter<0||d.counter>65535||d.state< -1||d.state>255||d.alarms<0||d.alarms>0xffffffffL)throw new JSONException("Invalid equipment header");JSONObject v=j.getJSONObject("values"),u=j.getJSONObject("units");if(v.length()>20)throw new JSONException("Too many measurements");java.util.Iterator<String> keys=v.keys();while(keys.hasNext()){String k=keys.next(),unit=u.getString(k);double n=v.getDouble(k);if(k.length()>50||unit.length()>10||!Double.isFinite(n)||Math.abs(n)>1e9)throw new JSONException("Invalid equipment measurement");d.add(k,n,unit);}JSONObject details=j.optJSONObject("details");if(details!=null){if(details.length()>16)throw new JSONException("Too many equipment details");java.util.Iterator<String> fields=details.keys();while(fields.hasNext()){String label=fields.next(),value=details.getString(label);if(label.length()>50||value.length()>100)throw new JSONException("Invalid equipment detail");d.details.put(label,value);}}return new EquipmentReading(time,address.toUpperCase(java.util.Locale.ROOT),name,d);}
}
